INSERT INTO schm_sp.service_master_data VALUES (35, 'catalogue questions', 'Catalogue questions', '{"questionnaire": {"title": "Beneficiary Definition Profile — Service Catalogue", "version": "1.0", "sections": [{"id": "applicant_type", "title": "Applicant Type", "questions": [{"id": "who_can_apply", "type": "multi_select", "options": ["Individual", "Institution / Organization", "Community Group", "Enterprise / MSME"], "question": "Who can apply for this service?"}]}, {"id": "age", "title": "Age", "questions": [{"id": "age_restriction", "type": "boolean", "question": "Is there an age restriction for this service?"}, {"id": "age_capture_method", "type": "multi_select", "options": ["Specific Age Range (numeric)", "Specific Date of Birth Range", "Age Bracket (predefined)"], "show_if": {"equals": true, "question_id": "age_restriction"}, "question": "If yes, how should age be captured?"}, {"id": "age_range", "type": "number_range", "fields": ["min_age", "max_age"], "show_if": {"contains": "Specific Age Range (numeric)", "question_id": "age_capture_method"}, "question": "Enter minimum and maximum age"}, {"id": "dob_range", "type": "date_range", "fields": ["born_after", "born_before"], "show_if": {"contains": "Specific Date of Birth Range", "question_id": "age_capture_method"}, "question": "Enter cutoff dates"}, {"id": "age_bracket", "type": "multi_select", "options": ["Minor (below 18)", "Young Adult (18–29)", "Adult (30–45)", "Middle Age (46–59)", "Senior (60+)"], "show_if": {"contains": "Age Bracket (predefined)", "question_id": "age_capture_method"}, "question": "Select applicable age bracket(s)"}]}, {"id": "gender", "title": "Gender", "questions": [{"id": "gender_specific", "type": "boolean", "question": "Is this service gender-specific?"}, {"id": "applicable_gender", "type": "multi_select", "options": ["Male", "Female", "Transgender", "Prefer not to disclose"], "show_if": {"equals": true, "question_id": "gender_specific"}, "question": "If yes, select applicable gender(s)"}]}, {"id": "location_residency", "title": "Location / Residency", "questions": [{"id": "location_restricted", "type": "boolean", "question": "Is this service restricted to applicants from a specific location?"}, {"id": "jurisdiction_level", "type": "multi_select", "options": ["State-specific", "District-specific", "Urban only", "Rural only", "Pan-India"], "show_if": {"equals": true, "question_id": "location_restricted"}, "question": "If yes, select the jurisdiction level"}, {"id": "residency_duration", "type": "single_select", "options": ["Not Required", "Native (born in state)", "Resident 5+ years", "Resident 1–5 years", "No minimum, recent residents allowed"], "question": "Is a minimum residency/domicile duration required?"}]}, {"id": "family_household", "title": "Family / Household Status", "questions": [{"id": "family_status_relevant", "type": "boolean", "question": "Does eligibility depend on family or marital status?"}, {"id": "marital_status", "type": "multi_select", "options": ["Unmarried", "Married", "Separated / Divorced", "Widow / Widower", "Single Parent"], "show_if": {"equals": true, "question_id": "family_status_relevant"}, "question": "If yes, select applicable status"}, {"id": "household_size_relevant", "type": "boolean", "question": "Does household size or number of dependents affect eligibility?"}, {"id": "household_size", "type": "multi_select", "options": ["None", "1–2", "3–5", "6+"], "show_if": {"equals": true, "question_id": "household_size_relevant"}, "question": "If yes, select household size"}]}, {"id": "social_category", "title": "Social Category", "questions": [{"id": "social_category_restricted", "type": "boolean", "question": "Is this service restricted by social category?"}, {"id": "social_category", "type": "multi_select", "options": ["General", "SC", "ST", "OBC", "EWS", "Minority"], "show_if": {"equals": true, "question_id": "social_category_restricted"}, "question": "If yes, select applicable category(ies)"}]}, {"id": "economic_income", "title": "Economic / Income Status", "questions": [{"id": "income_condition", "type": "boolean", "question": "Is there an income-based eligibility condition?"}, {"id": "income_slab", "type": "multi_select", "options": ["Below ₹1 Lakh", "₹1–3 Lakh", "₹3–6 Lakh", "₹6–10 Lakh", "Above ₹10 Lakh"], "show_if": {"equals": true, "question_id": "income_condition"}, "question": "If yes, select income slab(s)"}, {"id": "economic_status", "type": "multi_select", "options": ["APL", "BPL"], "question": "Or select economic status directly"}]}, {"id": "occupation_employment", "title": "Occupation / Employment", "questions": [{"id": "occupation_relevant", "type": "boolean", "question": "Does eligibility depend on occupation or employment type?"}, {"id": "occupation", "type": "multi_select", "options": ["Salaried", "Self-Employed / Business", "Farmer / Agricultural Worker", "Daily Wage Worker", "Student", "Homemaker", "Unemployed", "Retired"], "show_if": {"equals": true, "question_id": "occupation_relevant"}, "question": "If yes, select applicable occupation(s)"}, {"id": "employment_sector", "type": "multi_select", "options": ["Not Applicable", "Organized Sector", "Unorganized Sector", "Gig/Platform Work"], "question": "Is employment sector relevant?"}]}, {"id": "education", "title": "Education", "questions": [{"id": "education_required", "type": "boolean", "question": "Is there a minimum education qualification required?"}, {"id": "minimum_education", "type": "multi_select", "options": ["No Formal Education", "Primary", "Secondary", "Senior Secondary", "Graduate", "Postgraduate", "Professional/Vocational Certification"], "show_if": {"equals": true, "question_id": "education_required"}, "question": "If yes, select minimum level"}, {"id": "enrollment_status", "type": "single_select", "options": ["Not Applicable", "Currently Studying", "Not Studying"], "question": "Is current enrollment status relevant?"}]}, {"id": "health_care", "title": "Health / Care Needs", "questions": [