specific digital access to apply for this service?"}, {"id": "digital_access_type", "type": "multi_select", "options": ["Smartphone + Internet", "Feature Phone Only", "No Personal Device (assisted access needed)"], "show_if": {"equals": true, "question_id": "digital_access_required"}, "question": "If yes, select applicable category"}]}, {"id": "required_documents", "title": "Required Documents", "questions": [{"id": "mandatory_documents", "type": "multi_select", "options": ["Aadhaar", "Voter ID", "PAN", "Ration Card", "Domicile Certificate", "Caste Certificate", "Income Certificate", "Disability Certificate"], "question": "Which documents are mandatory for eligibility verification?"}]}], "configuration_rules": {"gating_question": true, "minimum_applicable_criteria": 3, "expand_only_relevant_sections": true}}}');
